    public function __construct(
        private readonly Connection $db,
        private readonly AttributeVocabulary $vocabulary,
        private readonly DuplicateGuard $duplicates,
    ) {
        parent::__construct();
    }

    #[\Override]
    protected function configure(): void
    {
        $this->addOption(
            'overwrite-ref',
            null,
            InputOption::VALUE_REQUIRED | InputOption::VALUE_IS_ARRAY,
            'source_ref of a pin whose approved edit this run may overwrite (repeatable). Without it, an edited row keeps its DB content.',
        );
    }

    #[\Override]
    protected function execute(InputInterface $input, OutputInterface $output): int
    {
        $io = new SymfonyStyle($input, $output);

        /** @var list<string> $overwriteRefs */
        $overwriteRefs = $input->getOption('overwrite-ref');
        $knownRefs = array_column(self::pins(), 'ref');
        $unknownRefs = array_diff($overwriteRefs, $knownRefs);
        if ([] !== $unknownRefs) {
            $io->error(sprintf(
                '--overwrite-ref matches no seeded pin: %s. Nothing was written.',
                implode(', ', $unknownRefs),
            ));

            return Command::INVALID;
        }
        if ([] !== $overwriteRefs) {
            $io->warning(sprintf(
                'Overwriting the approved edit(s) on: %s. The change_history rows stay, the current content does not.',
                implode(', ', $overwriteRefs),
            ));
        }

        try {
            $this->db->beginTransaction();
            $counts = [];
            $skipped = [];
            foreach (self::pins() as $pin) {
                $type = ItemType::fromParam($pin['letter']);
                $this->vocabulary->assertValid($type, $pin['attributes']);

                $held = $this->duplicates->existing(
                    $pin['letter'], $pin['name'], $pin['lat'], $pin['lng'], 'manual:'.$pin['ref'],
                );
                if (null !== $held) {
                    $skipped[] = DuplicateGuard::explain($pin['name'], ItemSource::Manual, $held);
                    continue;
                }

                $this->db->executeStatement(
                    \in_array($pin['ref'], $overwriteRefs, true) ? ItemUpsert::SQL_OVERWRITE_EDITED : ItemUpsert::SQL,
                    [
                        'letter' => $pin['letter'],
                        'name' => $pin['name'],
                        'geom' => json_encode(['type' => 'Point', 'coordinates' => [$pin['lng'], $pin['lat']]], \JSON_THROW_ON_ERROR),
                        'cc' => $pin['cc'] ?? self::DEFAULT_COUNTRY,
                        'sub' => $this->resolveSubdivisionId($pin['sub'] ?? self::DEFAULT_SUBDIVISION_CODE),
                        'state' => 'unverified',
                        'source' => 'manual',
                        'ref' => $pin['ref'],
                        'attrs' => json_encode($pin['attributes'], \JSON_THROW_ON_ERROR | \JSON_PRESERVE_ZERO_FRACTION),
                    ],
                );
                $counts[$pin['letter']] = ($counts[$pin['letter']] ?? 0) + 1;
            }
            $this->recomputeMembership();
            $this->db->commit();
        } catch (\InvalidArgumentException|\JsonException|DBALException $e) {
            if ($this->db->isTransactionActive()) {
                $this->db->rollBack();
            }
            $io->error($e->getMessage());

            return Command::FAILURE;
        }

        ksort($counts);
        foreach ($counts as $letter => $count) {
            $io->writeln(sprintf('  %s: %d pin(s)', $letter, $count));
        }
        if ([] !== $skipped) {
            $io->note(sprintf(
                "Skipped %d pin(s) that duplicate a row already in the catalog:\n  %s",
                \count($skipped),
                implode("\n  ", $skipped),
            ));
        }
        $io->success(sprintf('Seeded %d manual demo pin(s) across %d letter(s).', array_sum($counts), \count($counts)));

        /* docs/specs/climb-elevation.md §4 — measured keys survive a re-seed only while `route` is unchanged. */
        /** @var list<string> $unmeasured */
        $unmeasured = $this->db->fetchFirstColumn(
            // jsonb_exists, not `?`: DBAL treats `?` as a placeholder.
            "SELECT name FROM item WHERE source = 'manual' AND letter = 'N' AND NOT jsonb_exists(attributes, 'lineGrad') ORDER BY name",
        );
        if ([] !== $unmeasured) {
            $io->warning(sprintf(
                '%d climb(s) carry no measured gradients (new line, or never measured): %s. Run app:climbs:recompute --write, with the elevation source up - it answers zeros when Valhalla is down.',
                \count($unmeasured),
                implode(', ', $unmeasured),
            ));
        }

        return Command::SUCCESS;
    }

    /** @var array<string, int|null> resolved once per ISO 3166-2 code, not once per pin */
    private array $subdivisionIds = [];

    /** @return int|null world_subdivision.id, or null when world data isn't seeded yet */
    private function resolveSubdivisionId(string $code): ?int
    {
        if (!\array_key_exists($code, $this->subdivisionIds)) {
            $id = $this->db->fetchOne('SELECT id FROM world_subdivision WHERE code = :code', ['code' => $code]);
            $this->subdivisionIds[$code] = false !== $id ? (int) $id : null;
        }

        return $this->subdivisionIds[$code];
    }

    /** Only touches rows this command owns - never widens to the full item/recommended_route tables. */
    private function recomputeMembership(): void
    {
        // docs/specs/catalog-data-model.md §6 — smallest-area-wins; scoped to source=manual.
        $this->db->executeStatement(
            "UPDATE item SET region_id = m.region_id FROM (
                SELECT DISTINCT ON (i.id) i.id AS item_id, r.id AS region_id
                FROM item i JOIN region r ON ST_Contains(r.geom, ST_PointOnSurface(i.geom))
                WHERE i.source = 'manual'
                ORDER BY i.id, r.area_km2 ASC NULLS LAST, r.id ASC
             ) m WHERE item.id = m.item_id",
        );
    }

    /**
     * Wikimedia Commons photo URLs matching map.js `wc()`.
     *
     * @return array{sm: string, lg: string, credit: string, creditUrl: string, license: string, source: string}
     */
    private static function wc(string $file, string $credit, ?string $user, string $license): array
    {
        $enc = str_replace(['%21', '%27', '%28', '%29', '%2A'], ['!', "'", '(', ')', '*'], rawurlencode($file));
        $page = str_replace(' ', '_', $file);

        return [
            'sm' => "https://commons.wikimedia.org/wiki/Special:FilePath/{$enc}?width=520",
            'lg' => "https://commons.wikimedia.org/wiki/Special:FilePath/{$enc}?width=1400",
            'credit' => $credit,
            'creditUrl' => null !== $user ? 'https://commons.wikimedia.org/wiki/User:'.str_replace(' ', '_', $user) : '',
            'license' => $license,
            'source' => "https://commons.wikimedia.org/wiki/File:{$page}",
        ];
    }
}
